public static class DbDataSourceExtensions
{
    public static async Task<IEnumerable<T>> Query<T>(this DbDataSource dataSource, string sql, object parameters, CancellationToken cancellationToken)
    {
        await using var command = dataSource.CreateCommand(sql);
        foreach (var parameter in parameters.GetType().GetProperties())
        {
            var value = parameter.GetValue(parameters);
            var parameterName = parameter.Name;
            var parameter = command.CreateParameter();
            parameter.ParameterName = parameterName;
            parameter.Value = value;
            command.Parameters.Add(parameter);
        }

        await using var reader = await command.ExecuteReaderAsync(cancellationToken);
        var result = new List<T>();
        while (await reader.ReadAsync(cancellationToken))
        {
            result.Add(Activator.CreateInstance<T>(reader.GetValues()));
        }

        return result;
    }
}

